    assert.match(noResume.stderr, /--answer needs --resume/);
    const bad = nexus("--resume", "--answer", "nonsense", "do it");
    assert.equal(bad.status, 2, bad.stderr);
    assert.match(bad.stderr, /--answer expects <question id>=approve\|decline/);
  });
});
